<?php require_once "../config/database.php";require_once "../config/auth.php";require_role('driver');$uid=current_user()['id'];if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['id'];$status=$conn->real_escape_string($_POST['status']);$conn->query("UPDATE orders SET driver_id=$uid,status='$status' WHERE id=$id AND (driver_id IS NULL OR driver_id=$uid)");$stmt=$conn->prepare("INSERT INTO order_status_history(order_id,status,note) VALUES(?,?,?)");$note='Tài xế cập nhật trạng thái';$stmt->bind_param("iss",$id,$status,$note);$stmt->execute();header("Location:orders.php?id=$id");exit;}$id=(int)($_GET['id']??0);$o=$conn->query("SELECT o.*,r.name restaurant_name FROM orders o JOIN restaurants r ON r.id=o.restaurant_id WHERE o.id=$id")->fetch_assoc();?><!doctype html><html lang="vi"><head><meta charset="utf-8"><title>Xử lý đơn</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><div class="form"><h1>Đơn <?=$o['order_code']?></h1><p><?=htmlspecialchars($o['restaurant_name'])?></p><p><?=htmlspecialchars($o['delivery_address'])?></p><p>Hiện tại: <?=status_text($o['status'])?></p><form method="post"><input type="hidden" name="id" value="<?=$id?>"><select name="status"><option value="driver_received">Đã nhận đơn</option><option value="picked_up">Đã lấy món</option><option value="delivering">Đang giao</option><option value="completed">Đã giao</option></select><button class="btn">Cập nhật</button></form><p><a href="index.php">← Danh sách</a></p></div></main></body></html>